const COURSE_LESSON_HTML = {
  "kurssArticlesLesson": "\n  <h3>Nyjat</h3>\n\n  <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nyja gjermane nuk përputhet gjithmonë me gjininë e fjalës në shqip. Prandaj emrat mësohen më mirë së bashku me nyjën.</div>\n  </div>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Shembuj të nyjave</h4>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">der Tisch — tryezë</div>\n      <div class=\"kurss-example\">die Tür — derë</div>\n      <div class=\"kurss-example\">das Messer — thikë</div>\n      <div class=\"kurss-example\">das Mädchen — vajzë</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♂</span>Shpesh DER</h4>\n    <p class=\"artikuli-explain\">DER përdoret shpesh për persona meshkuj, ditët, muajt, stinët dhe disa fjalë me mbaresa të caktuara.</p>\n\n    <h5 class=\"artikuli-subtitle\">Rregullat</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-er → shpesh DER, për shembull: der Computer, der Lehrer <span class=\"artikuli-note\">por jo gjithmonë</span></div>\n      <div class=\"kurss-example\">-ling → shpesh DER, për shembull: der Schmetterling</div>\n      <div class=\"kurss-example\">-ismus → shpesh DER, për shembull: der Tourismus, der Kapitalismus</div>\n      <div class=\"kurss-example\">persona meshkuj → der Mann, der Vater</div>\n      <div class=\"kurss-example\">profesionet → der Lehrer, der Arzt</div>\n      <div class=\"kurss-example\">markat e makinave → der BMW, der Mercedes</div>\n      <div class=\"kurss-example\">ditët → der Montag, der Dienstag</div>\n      <div class=\"kurss-example\">muajt → der August, der Dezember</div>\n      <div class=\"kurss-example\">stinët → der Sommer, der Winter</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Shembuj</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">der Mann — burrë</div>\n      <div class=\"kurss-example\">der Vater — baba</div>\n      <div class=\"kurss-example\">der Montag — e hënë</div>\n      <div class=\"kurss-example\">der August — gusht</div>\n      <div class=\"kurss-example\">der Sommer — verë</div>\n      <div class=\"kurss-example\">der Lehrer — mësues</div>\n      <div class=\"kurss-example\">der Computer — kompjuter</div>\n      <div class=\"kurss-example\">der Schmetterling — flutur</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♀</span>Shpesh DIE</h4>\n    <p class=\"artikuli-explain\">DIE përdoret shpesh për persona femra, shumësin dhe fjalët me mbaresat -ung, -heit, -keit, -schaft, -ion, -tät, -ei.</p>\n\n    <h5 class=\"artikuli-subtitle\">Rregullat</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-ung → die Wohnung, die Rechnung</div>\n      <div class=\"kurss-example\">-heit → die Freiheit, die Gesundheit</div>\n      <div class=\"kurss-example\">-keit → die Möglichkeit</div>\n      <div class=\"kurss-example\">-schaft → die Mannschaft</div>\n      <div class=\"kurss-example\">-ion → die Nation</div>\n      <div class=\"kurss-example\">-tät → die Universität</div>\n      <div class=\"kurss-example\">-ei → die Polizei, die Bäckerei</div>\n      <div class=\"kurss-example\">persona femra → die Frau, die Mutter</div>\n      <div class=\"kurss-example\">markat e motoçikletave → die Harley-Davidson, die Yamaha</div>\n      <div class=\"kurss-example\">shumësi → die Autos, die Häuser</div>\n      <div class=\"kurss-example\">shumësi pothuajse gjithmonë → die Autos, die Häuser, die Kinder</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Shembuj</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Frau — grua</div>\n      <div class=\"kurss-example\">die Mutter — nënë</div>\n      <div class=\"kurss-example\">die Wohnung — banesë</div>\n      <div class=\"kurss-example\">die Rechnung — faturë</div>\n      <div class=\"kurss-example\">die Freiheit — liri</div>\n      <div class=\"kurss-example\">die Möglichkeit — mundësi</div>\n      <div class=\"kurss-example\">die Mannschaft — ekip</div>\n      <div class=\"kurss-example\">die Nation — komb</div>\n      <div class=\"kurss-example\">die Universität — universitet</div>\n      <div class=\"kurss-example\">die Polizei — polici</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>◇</span>Shpesh DAS</h4>\n    <p class=\"artikuli-explain\">DAS përdoret shpesh për zvogëlueset me -chen / -lein, shumë fjalë me -ment / -um dhe foljet e përdorura si emra.</p>\n\n    <h5 class=\"artikuli-subtitle\">Rregullat</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-chen → das Mädchen, das Häuschen</div>\n      <div class=\"kurss-example\">-lein → das Fräulein</div>\n      <div class=\"kurss-example\">-ment → das Instrument</div>\n      <div class=\"kurss-example\">-um → das Zentrum, das Museum</div>\n      <div class=\"kurss-example\">metalet → das Gold, das Silber, das Eisen</div>\n      <div class=\"kurss-example\">elementet kimike → das Eisen, das Kupfer</div>\n      <div class=\"kurss-example\">hotelet → das Hotel</div>\n      <div class=\"kurss-example\">ngjyrat si emra → das Rot, das Blau</div>\n      <div class=\"kurss-example\">folja si emër → das Essen, das Lernen</div>\n      <div class=\"kurss-example\">foljet si emra → das Essen, das Lernen, das Lesen</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Shembuj</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">das Kind — fëmijë</div>\n      <div class=\"kurss-example\">das Mädchen — vajzë</div>\n      <div class=\"kurss-example\">das Häuschen — shtëpizë</div>\n      <div class=\"kurss-example\">das Instrument — instrument</div>\n      <div class=\"kurss-example\">das Zentrum — qendër</div>\n      <div class=\"kurss-example\">das Museum — muze</div>\n      <div class=\"kurss-example\">das Essen — ngrënie / ushqim</div>\n      <div class=\"kurss-example\">das Lernen — mësim</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>!</span>Përjashtime të rëndësishme / mësoji me nyjën</h4>\n    <p class=\"artikuli-explain\">Për disa fjalë nyja nuk mund të përcaktohet me siguri nga mbaresa ose nga gjinia e fjalës në shqip. Këto mësohen më mirë së bashku me nyjën.</p>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Tür — derë</div>\n      <div class=\"kurss-example\">das Messer — thikë</div>\n      <div class=\"kurss-example\">die Sonne — diell</div>\n      <div class=\"kurss-example\">der Mond — hënë</div>\n      <div class=\"kurss-example\">das Mädchen — vajzë</div>\n      <div class=\"kurss-example\">das Auto — makinë</div>\n      <div class=\"kurss-example\">der Käse — djathë</div>\n      <div class=\"kurss-example\">die Gabel — pirun</div>\n    </div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Mbaresat dhe grupet e fjalëve ndihmojnë për të gjetur nyjën, por nuk janë rregull 100% i sigurt. Nëse nuk je i sigurt, mësoje fjalën së bashku me nyjën.</div>\n  </div>\n",
  "kurssPronounsLesson": "\n  <h3>Përemrat</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nominativ, Akkusativ dhe Dativ — format e përemrave.</div>\n  </div>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>N</span>Nominativ — kush?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich — unë</div><div class=\"kurss-example\">du — ti</div><div class=\"kurss-example\">er — ai</div><div class=\"kurss-example\">sie — ajo</div><div class=\"kurss-example\">es — ai / ajo</div><div class=\"kurss-example\">wir — ne</div><div class=\"kurss-example\">ihr — ju</div><div class=\"kurss-example\">sie — ata / ato</div><div class=\"kurss-example\">Sie — Ju (formale)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>A</span>Akkusativ — kë?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mich — mua</div><div class=\"kurss-example\">dich — ty</div><div class=\"kurss-example\">ihn — atë (m.)</div><div class=\"kurss-example\">sie — atë (f.)</div><div class=\"kurss-example\">es — atë</div><div class=\"kurss-example\">uns — ne</div><div class=\"kurss-example\">euch — ju</div><div class=\"kurss-example\">sie — ata / ato</div><div class=\"kurss-example\">Sie — Ju (formale)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>D</span>Dativ — kujt?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mir — mua</div><div class=\"kurss-example\">dir — ty</div><div class=\"kurss-example\">ihm — atij</div><div class=\"kurss-example\">ihr — asaj</div><div class=\"kurss-example\">uns — neve</div><div class=\"kurss-example\">euch — juve</div><div class=\"kurss-example\">ihnen — atyre</div><div class=\"kurss-example\">Ihnen — Juve (formale)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>?</span>Si ta zgjedhim formën?</h4>\n    <ul class=\"kurss-summary-list\"><li><span class=\"case-blue\">Nominativ</span> — kryefjala (kush e kryen veprimin?)</li><li><span class=\"case-red\">Akkusativ</span> — kundrinori i drejtë (kë?)</li><li><span class=\"case-green\">Dativ</span> — kundrinori i zhdrejtë (kujt?)</li></ul>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Shembuj</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">dich</span>. — Unë të shoh.</div><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">ihn</span>. — Unë e shoh atë.</div><div class=\"kurss-example\">Wir mögen <span class=\"case-red\">euch</span>. — Ne ju pëlqejmë.</div><div class=\"kurss-example\">Ich helfe <span class=\"case-green\">dir</span>. — Unë të ndihmoj.</div><div class=\"kurss-example\">Ich gebe <span class=\"case-green\">ihm</span> ein Buch. — Unë i jap atij një libër.</div><div class=\"kurss-example\">Wir danken <span class=\"case-green\">euch</span>. — Ne ju falënderojmë.</div></div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nominativ është gjithmonë kryefjala, kurse Akkusativ dhe Dativ janë kundrinorë. Shiko foljen dhe pyet: <span class=\"case-red\">kë?</span> apo <span class=\"case-green\">kujt?</span></div>\n  </div>\n",
  "kurssPronunciationLesson": "\n            <h3>Zanoret — të gjata dhe të shkurtra</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n              <span class=\"artikuli-info-icon\">i</span>\n              <div>Në gjermanisht zanoret mund të jenë të gjata ose të shkurtra. Kjo ndikon në shqiptimin e fjalës.</div>\n            </div>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Zanore e gjatë</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">warm (varm) — i ngrohtë</div><div class=\"kurss-example\">gut (gūt) — i mirë</div><div class=\"kurss-example\">Tat (tāt) — vepër / veprim</div><div class=\"kurss-example\">Flur (flūr) — korridor</div><div class=\"kurss-example\">Weg (vēk) — rrugë</div><div class=\"kurss-example\">Hut (hūt) — kapelë</div><div class=\"kurss-example\">Hof (hōf) — oborr</div><div class=\"kurss-example\">Schlaf (shlāf) — gjumë</div></div>\n              <p class=\"artikuli-explain\">Kur pas zanores vjen vetëm një bashkëtingëllore, zanorja shpesh shqiptohet e gjatë.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Zanore e shkurtër</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Pilz (pilc) — kërpudhë</div><div class=\"kurss-example\">Wort (vort) — fjalë</div><div class=\"kurss-example\">Mund (munt) — gojë</div><div class=\"kurss-example\">bald (balt) — së shpejti</div><div class=\"kurss-example\">scharf (sharf) — i mprehtë / djegës</div><div class=\"kurss-example\">Feld (felt) — fushë / arë</div><div class=\"kurss-example\">voll (fol) — plot / i mbushur</div></div>\n              <p class=\"artikuli-explain\">Kur pas zanores vijnë dy ose më shumë bashkëtingëllore, zanorja shpesh shqiptohet e shkurtër.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Mbaresat en / el / er</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">singen (zingën) — këndoj</div><div class=\"kurss-example\">tragen (trāgën) — mbaj / bart</div><div class=\"kurss-example\">Garten (gartën) — kopsht</div><div class=\"kurss-example\">Vogel (fōgël) — zog</div><div class=\"kurss-example\">Segel (zēgël) — vel</div><div class=\"kurss-example\">Braten (brātën) — mish i pjekur / rosto</div><div class=\"kurss-example\">Bogen (bōgën) — hark</div><div class=\"kurss-example\">Spiegel (shpīgël) — pasqyrë</div><div class=\"kurss-example\">Finger (fingër) — gisht</div><div class=\"kurss-example\">Halter (haltër) — mbajtëse</div><div class=\"kurss-example\">Arbeiter (arbajtër) — punëtor</div><div class=\"kurss-example\">Häuser (hojzër) — shtëpi (shumës)</div><div class=\"kurss-example\">wieder (vīdër) — përsëri</div><div class=\"kurss-example\">breiter (brajtër) — më i gjerë</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Shkronja h si shenjë gjatësie</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Rahmen (rāmën) — kornizë</div><div class=\"kurss-example\">Ohr (ōr) — vesh</div><div class=\"kurss-example\">Kohle (kōlë) — qymyr</div><div class=\"kurss-example\">Zahl (cāl) — numër</div><div class=\"kurss-example\">ihn (īn) — atë (për mashkull)</div><div class=\"kurss-example\">ihm (īm) — atij</div><div class=\"kurss-example\">Huhn (hūn) — pulë</div><div class=\"kurss-example\">nahm (nām) — mori</div><div class=\"kurss-example\">nehmen (nēmën) — marr</div><div class=\"kurss-example\">Schuh (shū) — këpucë</div></div>\n              <p class=\"artikuli-explain\">Në disa fjalë h e zgjat zanoren paraardhëse. Në këto raste h zakonisht nuk shqiptohet.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Mbaresat me e</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Lampe (lampë) — llambë</div><div class=\"kurss-example\">Hase (hāzë) — lepur</div><div class=\"kurss-example\">Knabe (knābë) — djalë</div><div class=\"kurss-example\">Rabe (rābë) — korb</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>I-ja e gjatë = ie</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">die (dī) — nyja «die»</div><div class=\"kurss-example\">diese (dīzë) — kjo / këto</div><div class=\"kurss-example\">wieder (vīdër) — përsëri</div><div class=\"kurss-example\">Fliege (flīgë) — mizë</div><div class=\"kurss-example\">Ziege (cīgë) — dhi</div><div class=\"kurss-example\">Stiel (shtīl) — bisht / kërcell</div><div class=\"kurss-example\">Dieb (dīp) — hajdut</div><div class=\"kurss-example\">hier (hīr) — këtu</div></div>\n              <p class=\"artikuli-explain\">I-ja e gjatë në gjermanisht shpesh shkruhet si ie.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Zanoret e dyfishta</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Saal (zāl) — sallë</div><div class=\"kurss-example\">Saat (zāt) — farë / mbjellje</div><div class=\"kurss-example\">Staat (shtāt) — shtet</div><div class=\"kurss-example\">Beere (bērë) — kokërr frute (mani, dredhëz etj.)</div><div class=\"kurss-example\">See (zē) — liqen / det</div><div class=\"kurss-example\">Beet (bēt) — lehe (në kopsht)</div><div class=\"kurss-example\">Boot (bōt) — varkë</div><div class=\"kurss-example\">Moor (mōr) — moçal / kënetë</div><div class=\"kurss-example\">Moos (mōs) — myshk</div></div>\n              <p class=\"artikuli-explain\">Zanoret e dyfishta zakonisht shqiptohen të gjata.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ä</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Wand (vant) — mur</div><div class=\"kurss-example\">Wände (vendë) — mure</div><div class=\"kurss-example\">Vater (fātër) — baba / atë</div><div class=\"kurss-example\">Väter (fētër) — etër</div><div class=\"kurss-example\">Schrank (shrank) — dollap</div><div class=\"kurss-example\">Schränke (shrenkë) — dollapë</div><div class=\"kurss-example\">Bank (bank) — stol / bankë</div><div class=\"kurss-example\">Bänke (benkë) — stola</div><div class=\"kurss-example\">Tal (tāl) — luginë</div><div class=\"kurss-example\">Täler (tēlër) — lugina</div></div>\n              <p class=\"artikuli-explain\">ä është zanorja a e ndryshuar (umlaut).</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ö</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Rose (rōzë) — trëndafil</div><div class=\"kurss-example\">Röschen (rēs-hjën) — trëndafil i vogël</div><div class=\"kurss-example\">Ofen (ōfën) — sobë / furrë</div><div class=\"kurss-example\">Öfen (ēfën) — soba / furra</div><div class=\"kurss-example\">Rock (rok) — fund (veshje)</div><div class=\"kurss-example\">Röcke (rekë) — funde (veshje)</div></div>\n              <p class=\"artikuli-explain\">ö është zanorja o e ndryshuar (umlaut).</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ü</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">kurz (kurc) — i shkurtër</div><div class=\"kurss-example\">kürzer (kyrcër) — më i shkurtër</div><div class=\"kurss-example\">Kunst (kunst) — art</div><div class=\"kurss-example\">Künste (kynstë) — arte</div><div class=\"kurss-example\">Mutter (mutër) — nënë</div><div class=\"kurss-example\">Mütter (mytër) — nëna</div></div>\n              <p class=\"artikuli-explain\">ü është zanorja u e ndryshuar (umlaut).</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Diftongjet: äu</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Baum (baum) — pemë</div><div class=\"kurss-example\">Bäume (bojmë) — pemë (shumës)</div><div class=\"kurss-example\">Haus (haus) — shtëpi</div><div class=\"kurss-example\">Häuser (hojzër) — shtëpi (shumës)</div><div class=\"kurss-example\">Strauch (shtrauh) — shkurre</div><div class=\"kurss-example\">Sträucher (shtrojhjër) — shkurre (shumës)</div><div class=\"kurss-example\">Maus (maus) — mi</div><div class=\"kurss-example\">Mäuse (mojzë) — minj</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Diftongjet: eu</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">heute (hojtë) — sot</div><div class=\"kurss-example\">Leute (lojtë) — njerëz</div><div class=\"kurss-example\">neu (noj) — i ri</div><div class=\"kurss-example\">neun (nojn) — nëntë</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Diftongjet: ei</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">mein (majn) — im</div><div class=\"kurss-example\">dein (dajn) — yt</div><div class=\"kurss-example\">sein (zajn) — i tij / (folja) të jesh</div><div class=\"kurss-example\">frei (fraj) — i lirë</div><div class=\"kurss-example\">arbeiten (arbajtën) — punoj</div></div>\n            </section>\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>✓</span>Shënime shqiptimi për mësimin 2</h4>\n              <ul class=\"kurss-summary-list\"><li>në fjalët ich, nicht, rechnen, zeichnen «ch» shqiptohet butë (si «hj» shqip)</li><li>në fjalët arbeiten dhe zeichnen «ei» shqiptohet si «aj»</li><li>«sp» në fillim të fjalës shqiptohet si «shp»</li><li>në foljen tun shkronja «u» shqiptohet e gjatë</li></ul>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>✓</span>Përmbledhje</h4>\n              <ul class=\"kurss-summary-list\"><li>një bashkëtingëllore pas zanores → shpesh zanore e gjatë</li><li>dy ose më shumë bashkëtingëllore → shpesh zanore e shkurtër</li><li>h mund ta zgjatë zanoren</li><li>ie shpesh shënon i-në e gjatë</li><li>zanoret e dyfishta zakonisht janë të gjata</li></ul>\n            </section>",
  "kurssConsonantsLesson": "\n            <h3>Bashkëtingëlloret dhe kombinimet e shkronjave</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n              <span class=\"artikuli-info-icon\">i</span>\n              <div>Në gjermanisht disa bashkëtingëllore dhe kombinime shkronjash shqiptohen ndryshe nga si shkruhen. Në këtë mësim janë shembujt më të rëndësishëm për fillestarët.</div>\n            </div>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Bashkëtingëlloret</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">das Rad (rāt) — rrotë</div><div class=\"kurss-example\">die Räder (rēdër) — rrota</div><div class=\"kurss-example\">Bad (bāt) — banjë</div><div class=\"kurss-example\">Bäder (bēdër) — banja</div></div>\n              <p class=\"artikuli-explain\">Në fund të fjalës bashkëtingëlloret shpesh nuk shqiptohen ashtu si shkruhen (p.sh. d shqiptohet si t, b si p, g si k).</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ch</h4>\n              <p class=\"artikuli-explain\">«ch» mund të shqiptohet butë ose fortë. Në disa fjalë tingëllon si «hj» shqip, në të tjera si një «h» e fortë e fyti, më afër «k»-së.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">rechnen (rehjnën) — llogarit</div><div class=\"kurss-example\">zeichnen (cajhjnën) — vizatoj</div><div class=\"kurss-example\">nicht (nihjt) — jo / nuk</div><div class=\"kurss-example\">schlecht (shlehjt) — i keq</div><div class=\"kurss-example\">mich (mihj) — mua / më</div><div class=\"kurss-example\">dich (dihj) — ty / të</div><div class=\"kurss-example\">Strauch (shtrauh) — shkurre</div><div class=\"kurss-example\">noch (noh) — ende / akoma</div><div class=\"kurss-example\">Nacht (naht) — natë</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>sch</h4>\n              <p class=\"artikuli-explain\">«sch» në gjermanisht shqiptohet si «sh» shqip.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Schule (shūlë) — shkollë</div><div class=\"kurss-example\">Schüler (shȳlër) — nxënës</div><div class=\"kurss-example\">Schiff (shif) — anije</div><div class=\"kurss-example\">Schraube (shraubë) — vidë</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>sp dhe st në fillim të fjalës</h4>\n              <p class=\"artikuli-explain\">Në fillim të fjalës ose të rrokjes «sp» shpesh shqiptohet si «shp», ndërsa «st» si «sht».</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">spielen (shpīlën) — luaj</div><div class=\"kurss-example\">Sprung (shprung) — kërcim</div><div class=\"kurss-example\">stehen (shtēën) — qëndroj (në këmbë)</div><div class=\"kurss-example\">Stall (shtal) — stallë / ahur</div><div class=\"kurss-example\">Stand (shtant) — pozitë / vend / stendë</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>qu</h4>\n              <p class=\"artikuli-explain\">«qu» në gjermanisht zakonisht shqiptohet si «kv».</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Qual (kvāl) — mundim / vuajtje</div><div class=\"kurss-example\">Quartier (kvartīr) — lagje / vendstrehim</div><div class=\"kurss-example\">quer (kvēr) — tërthor / kryq</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>s dhe z</h4>\n              <p class=\"artikuli-explain\">Në fillim të fjalës «s» shpesh tingëllon si «z». Shkronja «z» në gjermanisht tingëllon si «c» shqip.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">sagen (zāgën) — them</div><div class=\"kurss-example\">singen (zingën) — këndoj</div><div class=\"kurss-example\">Rose (rōzë) — trëndafil</div><div class=\"kurss-example\">Zahl (cāl) — numër</div><div class=\"kurss-example\">Zeit (cajt) — kohë</div><div class=\"kurss-example\">Zink (cink) — zink</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>v</h4>\n              <p class=\"artikuli-explain\">Në gjermanisht «v» shpesh shqiptohet si «f». Në fjalët e huaja shpesh tingëllon si «v» shqip.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Vater (fātër) — baba / atë</div><div class=\"kurss-example\">von (fon) — nga / prej</div><div class=\"kurss-example\">viel (fīl) — shumë</div><div class=\"kurss-example\">vier (fīr) — katër</div><div class=\"kurss-example\">Villa (vila) — vilë</div><div class=\"kurss-example\">Klavier (klavīr) — piano</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>x dhe y</h4>\n              <p class=\"artikuli-explain\">«x» shqiptohet si «ks» (jo si «x» shqip). «y» në disa fjalë shqiptohet si «ü», d.m.th. si «y» shqip.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Felix (fēliks) — Feliks</div><div class=\"kurss-example\">Axt (akst) — sëpatë</div><div class=\"kurss-example\">Mystik (mȳstik) — mistikë</div><div class=\"kurss-example\">Mythe (mȳtë) — mit</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ß</h4>\n              <p class=\"artikuli-explain\">«ß» në gjermanisht shqiptohet si «s».</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Fuß (fūs) — këmbë / shputë</div><div class=\"kurss-example\">Füße (fȳsë) — këmbë / shputa (shumës)</div><div class=\"kurss-example\">Grüße (grȳsë) — përshëndetje (shumës)</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>✓</span>Përmbledhje</h4>\n              <ul class=\"kurss-summary-list\"><li>sch → sh</li><li>sp / st në fillim → shp / sht</li><li>qu → kv</li><li>z → c</li><li>v shpesh → f</li><li>x → ks</li><li>ß → s</li></ul>\n            </section>",
  "kurssVerbBasicsLesson": "\n            <h3>Bazat e foljeve</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n              <span class=\"artikuli-info-icon\">i</span>\n              <div>Foljet e mësimit 1 dhe format e tyre (zgjedhimi)</div>\n            </div>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Foljet</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">kommen — vij</div><div class=\"kurss-example\">gehen — shkoj</div><div class=\"kurss-example\">stehen — qëndroj në këmbë</div><div class=\"kurss-example\">singen — këndoj</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>kommen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich komme — unë vij</div><div class=\"kurss-example\">du kommst — ti vjen</div><div class=\"kurss-example\">er kommt — ai vjen</div><div class=\"kurss-example\">sie kommt — ajo vjen</div><div class=\"kurss-example\">wir kommen — ne vijmë</div><div class=\"kurss-example\">ihr kommt — ju vini</div><div class=\"kurss-example\">sie kommen — ata / ato vijnë</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>gehen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich gehe — unë shkoj</div><div class=\"kurss-example\">du gehst — ti shkon</div><div class=\"kurss-example\">er geht — ai shkon</div><div class=\"kurss-example\">sie geht — ajo shkon</div><div class=\"kurss-example\">wir gehen — ne shkojmë</div><div class=\"kurss-example\">ihr geht — ju shkoni</div><div class=\"kurss-example\">sie gehen — ata / ato shkojnë</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>stehen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich stehe — unë qëndroj në këmbë</div><div class=\"kurss-example\">du stehst — ti qëndron në këmbë</div><div class=\"kurss-example\">er steht — ai qëndron në këmbë</div><div class=\"kurss-example\">sie steht — ajo qëndron në këmbë</div><div class=\"kurss-example\">wir stehen — ne qëndrojmë në këmbë</div><div class=\"kurss-example\">ihr steht — ju qëndroni në këmbë</div><div class=\"kurss-example\">sie stehen — ata / ato qëndrojnë në këmbë</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>singen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich singe — unë këndoj</div><div class=\"kurss-example\">du singst — ti këndon</div><div class=\"kurss-example\">er singt — ai këndon</div><div class=\"kurss-example\">sie singt — ajo këndon</div><div class=\"kurss-example\">wir singen — ne këndojmë</div><div class=\"kurss-example\">ihr singt — ju këndoni</div><div class=\"kurss-example\">sie singen — ata / ato këndojnë</div></div>\n            </section>\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Foljet e mësimit 2</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">spielen — luaj</div><div class=\"kurss-example\">arbeiten — punoj</div><div class=\"kurss-example\">fragen — pyes</div><div class=\"kurss-example\">antworten — përgjigjem</div><div class=\"kurss-example\">rechnen — llogarit</div><div class=\"kurss-example\">zeichnen — vizatoj</div><div class=\"kurss-example\">tun — bëj</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>spielen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich spiele — unë luaj</div><div class=\"kurss-example\">du spielst — ti luan</div><div class=\"kurss-example\">er spielt — ai luan</div><div class=\"kurss-example\">sie spielt — ajo luan</div><div class=\"kurss-example\">wir spielen — ne luajmë</div><div class=\"kurss-example\">ihr spielt — ju luani</div><div class=\"kurss-example\">sie spielen — ata / ato luajnë</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>arbeiten</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich arbeite — unë punoj</div><div class=\"kurss-example\">du arbeitest — ti punon</div><div class=\"kurss-example\">er arbeitet — ai punon</div><div class=\"kurss-example\">sie arbeitet — ajo punon</div><div class=\"kurss-example\">wir arbeiten — ne punojmë</div><div class=\"kurss-example\">ihr arbeitet — ju punoni</div><div class=\"kurss-example\">sie arbeiten — ata / ato punojnë</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>fragen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich frage — unë pyes</div><div class=\"kurss-example\">du fragst — ti pyet</div><div class=\"kurss-example\">er fragt — ai pyet</div><div class=\"kurss-example\">sie fragt — ajo pyet</div><div class=\"kurss-example\">wir fragen — ne pyesim</div><div class=\"kurss-example\">ihr fragt — ju pyetni</div><div class=\"kurss-example\">sie fragen — ata / ato pyesin</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>antworten</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich antworte — unë përgjigjem</div><div class=\"kurss-example\">du antwortest — ti përgjigjesh</div><div class=\"kurss-example\">er antwortet — ai përgjigjet</div><div class=\"kurss-example\">sie antwortet — ajo përgjigjet</div><div class=\"kurss-example\">wir antworten — ne përgjigjemi</div><div class=\"kurss-example\">ihr antwortet — ju përgjigjeni</div><div class=\"kurss-example\">sie antworten — ata / ato përgjigjen</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>rechnen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich rechne — unë llogarit</div><div class=\"kurss-example\">du rechnest — ti llogarit</div><div class=\"kurss-example\">er rechnet — ai llogarit</div><div class=\"kurss-example\">sie rechnet — ajo llogarit</div><div class=\"kurss-example\">wir rechnen — ne llogaritim</div><div class=\"kurss-example\">ihr rechnet — ju llogaritni</div><div class=\"kurss-example\">sie rechnen — ata / ato llogaritin</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>zeichnen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich zeichne — unë vizatoj</div><div class=\"kurss-example\">du zeichnest — ti vizaton</div><div class=\"kurss-example\">er zeichnet — ai vizaton</div><div class=\"kurss-example\">sie zeichnet — ajo vizaton</div><div class=\"kurss-example\">wir zeichnen — ne vizatojmë</div><div class=\"kurss-example\">ihr zeichnet — ju vizatoni</div><div class=\"kurss-example\">sie zeichnen — ata / ato vizatojnë</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>tun</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich tue — unë bëj</div><div class=\"kurss-example\">du tust — ti bën</div><div class=\"kurss-example\">er tut — ai bën</div><div class=\"kurss-example\">sie tut — ajo bën</div><div class=\"kurss-example\">wir tun — ne bëjmë</div><div class=\"kurss-example\">ihr tut — ju bëni</div><div class=\"kurss-example\">sie tun — ata / ato bëjnë</div></div>\n            </section>",
  "kurssSentenceStructureLesson": "\n            <h3>Ndërtimi i fjalisë</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n              <span class=\"artikuli-info-icon\">i</span>\n              <div>Në fjalinë pyetëse, folja në gjermanisht zakonisht qëndron në vendin e parë.</div>\n            </div>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Shembuj</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Du kommst. — Ti vjen.</div><div class=\"kurss-example\">Kommst du? — A vjen ti?</div><div class=\"kurss-example\">Er singt. — Ai këndon.</div><div class=\"kurss-example\">Singt er? — A këndon ai?</div><div class=\"kurss-example\">Stehst du? — A qëndron ti?</div><div class=\"kurss-example\">Ja, ich stehe. — Po, unë qëndroj.</div><div class=\"kurss-example\">Geht ihr? — A shkoni ju?</div><div class=\"kurss-example\">Ja, wir gehen. — Po, ne shkojmë.</div></div>\n            </section>\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Pyetje me “was”</h4>\n              <p class=\"artikuli-explain\">Nëse pyetja fillon me një fjalë pyetëse, folja në gjermanisht zakonisht qëndron menjëherë pas fjalës pyetëse.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Was tust du? — Çfarë bën ti?</div><div class=\"kurss-example\">Was tut er? — Çfarë bën ai?</div><div class=\"kurss-example\">Was tut sie? — Çfarë bën ajo?</div><div class=\"kurss-example\">Was tun sie? — Çfarë bëjnë ata / ato?</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Mohimi me “nicht”</h4>\n              <p class=\"artikuli-explain\">Nëse mohimi “nicht” i referohet foljes, në gjermanisht ai zakonisht qëndron pas foljes.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Ich spiele nicht. — Unë nuk luaj.</div><div class=\"kurss-example\">Paul fragt nicht. — Pauli nuk pyet.</div><div class=\"kurss-example\">Er kommt nicht. — Ai nuk vjen.</div><div class=\"kurss-example\">Sie singen nicht. — Ata / ato nuk këndojnë.</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Fjali nga mësimi 2</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Spielst du? — A luan ti?</div><div class=\"kurss-example\">Nein, ich spiele nicht, ich arbeite. — Jo, unë nuk luaj, unë punoj.</div><div class=\"kurss-example\">Paul fragt nicht, er arbeitet. — Pauli nuk pyet, ai punon.</div><div class=\"kurss-example\">Arbeitest du? — A punon ti?</div><div class=\"kurss-example\">Nein, ich arbeite nicht, ich singe. — Jo, unë nuk punoj, unë këndoj.</div><div class=\"kurss-example\">Was tut Paul? — Çfarë bën Pauli?</div><div class=\"kurss-example\">Er spielt. — Ai luan.</div><div class=\"kurss-example\">Was tut Marie? — Çfarë bën Maria?</div><div class=\"kurss-example\">Sie singt. — Ajo këndon.</div><div class=\"kurss-example\">Paul spielt, aber Marie singt. — Pauli luan, por Maria këndon.</div><div class=\"kurss-example\">Singt ihr? — A këndoni ju?</div><div class=\"kurss-example\">Nein, wir singen nicht, wir arbeiten. — Jo, ne nuk këndojmë, ne punojmë.</div><div class=\"kurss-example\">Was tun Paul und Marie? — Çfarë bëjnë Pauli dhe Maria?</div><div class=\"kurss-example\">Sie fragen. — Ata pyesin.</div><div class=\"kurss-example\">Sie antworten nicht. — Ata nuk përgjigjen.</div><div class=\"kurss-example\">Wer arbeitet? — Kush punon?</div><div class=\"kurss-example\">Wir arbeiten. — Ne punojmë.</div><div class=\"kurss-example\">Wir rechnen und zeichnen. — Ne llogaritim dhe vizatojmë.</div><div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen. — Ata / ato vijnë, pyesin, përgjigjen, punojnë, luajnë, këndojnë dhe shkojnë.</div></div>\n            </section>",
  "kurssLesson2": "            <h3>Mësimi 2</h3>\n            <p class=\"kurss-lesson-intro\">Mësimi i dytë: dialogë, fjalë, shqiptim, gramatikë dhe përkthim.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialogë / fjali</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">Spielst du?<br>Nein, ich spiele nicht, ich arbeite.</div>\n                  <div class=\"kurss-example\">Paul fragt nicht, er arbeitet.</div>\n                  <div class=\"kurss-example\">Arbeitest du?<br>Nein, ich arbeite nicht, ich singe.</div>\n                  <div class=\"kurss-example\">Was tut Paul?<br>Er spielt.</div>\n                  <div class=\"kurss-example\">Was tut Marie?<br>Sie singt.</div>\n                  <div class=\"kurss-example\">Paul spielt, aber Marie singt.</div>\n                  <div class=\"kurss-example\">Singt ihr?<br>Nein, wir singen nicht, wir arbeiten.</div>\n                  <div class=\"kurss-example\">Was tun Paul und Marie?<br>Sie fragen.<br>Sie antworten nicht.</div>\n                  <div class=\"kurss-example\">Wer arbeitet?<br>Wir arbeiten.<br>Wir rechnen und zeichnen.</div>\n                  <div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen.</div>\n                </div>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Fjalët</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">spielen — luaj</div>\n                  <div class=\"kurss-example\">nein — jo</div>\n                  <div class=\"kurss-example\">nicht — nuk</div>\n                  <div class=\"kurss-example\">arbeiten — punoj</div>\n                  <div class=\"kurss-example\">fragen — pyes</div>\n                  <div class=\"kurss-example\">was tut er? — çfarë bën ai?</div>\n                  <div class=\"kurss-example\">was tun sie? — çfarë bëjnë ata / ato?</div>\n                  <div class=\"kurss-example\">aber — por</div>\n                  <div class=\"kurss-example\">antworten — përgjigjem</div>\n                  <div class=\"kurss-example\">rechnen — llogaris</div>\n                  <div class=\"kurss-example\">zeichnen — vizatoj</div>\n                  <div class=\"kurss-example\">Marie — Maria</div>\n                </div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Shqiptimi</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Në fjalët ich, nicht, rechnen, zeichnen tingulli ch shqiptohet butë, afërsisht si h-ja e lehtë para i-së në fjalët shqipe hije, hiç.</div><div class=\"kurss-example\">Në fjalët arbeiten, zeichnen diftongu ei shqiptohet afërsisht si aj në fjalën shqipe vaj.</div><div class=\"kurss-example\">Grupi i bashkëtingëlloreve sp shqiptohet si shp: spielen (shpiilen).</div><div class=\"kurss-example\">Te folja tun, u shqiptohet e gjatë në të gjitha vetat.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramatika</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>1</span>Mbaresat me e</h4>\n                  <div class=\"lesson1-grammar-note\">Nëse tema e foljes mbaron me t, d, chn, gjatë zgjedhimit para mbaresave -st dhe -t vendoset një e.</div>\n                  <h5 class=\"lesson2-subtitle\">arbeiten</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich arbeite</div><div class=\"kurss-example\">du arbeitest</div><div class=\"kurss-example\">er arbeitet</div><div class=\"kurss-example\">sie arbeitet</div><div class=\"kurss-example\">wir arbeiten</div><div class=\"kurss-example\">ihr arbeitet</div><div class=\"kurss-example\">sie arbeiten</div></div>\n                  <h5 class=\"lesson2-subtitle\">rechnen</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich rechne</div><div class=\"kurss-example\">du rechnest</div><div class=\"kurss-example\">er rechnet</div><div class=\"kurss-example\">sie rechnet</div><div class=\"kurss-example\">wir rechnen</div><div class=\"kurss-example\">ihr rechnet</div><div class=\"kurss-example\">sie rechnen</div></div>\n                  <h5 class=\"lesson2-subtitle\">tun</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich tue</div><div class=\"kurss-example\">du tust</div><div class=\"kurss-example\">er tut</div><div class=\"kurss-example\">sie tut</div><div class=\"kurss-example\">wir tun</div><div class=\"kurss-example\">ihr tut</div><div class=\"kurss-example\">sie tun</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>2</span>Fjala pyetëse</h4>\n                  <div class=\"lesson1-grammar-note\">Në fjalitë pyetëse që fillojnë me një fjalë pyetëse, p.sh.: çfarë? kush? cili? pse? përse? etj., folja qëndron menjëherë pas fjalës pyetëse.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Was tust du? — Çfarë bën ti?</div><div class=\"kurss-example\">Was tut er? — Çfarë bën ai?</div><div class=\"kurss-example\">Was tut sie? — Çfarë bën ajo?</div><div class=\"kurss-example\">Was tun sie? — Çfarë bëjnë ata / ato?</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>3</span>Mohimi me nicht</h4>\n                  <div class=\"lesson1-grammar-note\">Nëse mohimi nicht i referohet foljes, fjala mohuese qëndron pas foljes.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Er kommt nicht. — Ai nuk vjen.</div><div class=\"kurss-example\">Sie singen nicht. — Ata nuk këndojnë.</div></div>\n                </section>\n              </div>\n            </details>\n                                    <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Përkthe</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson2-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Mësimi 2: kartelë përkthimi\">\n                    <span class=\"lesson1-training-progress\">Mësimi 2 · Përkthe: 1 / 15</span>\n                    <span class=\"lesson1-training-text\">Kush pyet?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Kliko mbi kartelë për të parë përkthimin në gjermanisht. Pas përgjigjes, klikimi tjetër shfaq kartelën e radhës.</p>\n                </div>\n              </div>\n            </details>",
  "kurssLesson6": "\n    <h3>Mësimi 6</h3>\n    <p class=\"kurss-lesson-intro\">Numrat, shumësi, umlautet dhe format e shumësit të emrave.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialogë / fjali</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier liegt ein Bleistift.</div><div class=\"kurss-example\">Dort liegen einige Messer.</div><div class=\"kurss-example\">Edgar nimmt ein Messer, zwei Messer, drei Messer.</div><div class=\"kurss-example\">Er legt die Messer wieder hin.</div><div class=\"kurss-example\">Alle Messer sind scharf.</div><div class=\"kurss-example\">Dann nimmt er wieder ein Messer.</div><div class=\"kurss-example\">Er macht das Messer auf.</div><div class=\"kurss-example\">Er nimmt den Bleistift.</div><div class=\"kurss-example\">Er spitzt den Bleistift an.</div><div class=\"kurss-example\">Er legt das Messer hin.</div><div class=\"kurss-example\">Er setzt sich und zeichnet.</div><div class=\"kurss-example\">Was zeichnet er? Er zeichnet einen Schlüssel.</div><div class=\"kurss-example\">Gertrud zeichnet ein Fenster und eine Tafel.</div><div class=\"kurss-example\">Anna zeichnet einen Garten.</div><div class=\"kurss-example\">Hier liegen vier Löffel.</div><div class=\"kurss-example\">Dort liegen fünf Nadeln.</div><div class=\"kurss-example\">Gertrud kommt und zählt die Löffel: das ist ein Löffel; das sind zwei, drei, vier Löffel.</div><div class=\"kurss-example\">Anna zählt die Nadeln: das ist eine Nadel; das sind zwei, drei, vier, fünf Nadeln.</div><div class=\"kurss-example\">Wieviel Nadeln sind hier?</div><div class=\"kurss-example\">Hier ist eine Nadel.</div><div class=\"kurss-example\">Dort sind zwei, drei, vier Nadeln.</div><div class=\"kurss-example\">Fünf Schlüssel sind hier.</div><div class=\"kurss-example\">Sechs Löffel sind dort.</div><div class=\"kurss-example\">Was ist das?</div><div class=\"kurss-example\">Das ist ein Hammer. Das sind fünf Hämmer.</div><div class=\"kurss-example\">Das ist ein Deckel. Das sind sechs Deckel.</div><div class=\"kurss-example\">Das ist ein Eimer. Das sind sieben Eimer.</div><div class=\"kurss-example\">Das ist ein Teller. Das sind acht Teller.</div><div class=\"kurss-example\">Das ist ein Wagen. Das sind neun Wagen.</div><div class=\"kurss-example\">Das ist ein Schlitten. Das sind zehn Schlitten.</div><div class=\"kurss-example\">Wie sind die Dinge?</div><div class=\"kurss-example\">Der Hammer ist klein. Die Hämmer sind klein.</div><div class=\"kurss-example\">Der Deckel ist groß. Die Deckel sind groß.</div><div class=\"kurss-example\">Der Eimer ist voll. Die Eimer sind voll.</div><div class=\"kurss-example\">Der Teller ist leer. Die Teller sind leer.</div><div class=\"kurss-example\">Der Wagen ist schwer. Die Wagen sind schwer.</div><div class=\"kurss-example\">Der Schlitten ist leicht. Die Schlitten sind leicht.</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Fjalët</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">liegt — ndodhet, është, rri shtrirë</div><div class=\"kurss-example\">der Bleistift (blajshtift) — laps</div><div class=\"kurss-example\">einige (ajnige) — disa</div><div class=\"kurss-example\">hinlegen — vendos</div><div class=\"kurss-example\">legt hin — vendos</div><div class=\"kurss-example\">wieder (viider) — përsëri</div><div class=\"kurss-example\">aufmachen — hap</div><div class=\"kurss-example\">er macht auf — ai hap</div><div class=\"kurss-example\">anspitzen (anshpicen) — mpreh</div><div class=\"kurss-example\">er spitzt an — ai mpreh</div><div class=\"kurss-example\">sich setzen — ulem</div><div class=\"kurss-example\">setzt sich — ulet</div><div class=\"kurss-example\">der Schlüssel (shlysel) — çelës</div><div class=\"kurss-example\">das Fenster (fenster) — dritare</div><div class=\"kurss-example\">die Tafel (dii taafel) — dërrasë e zezë</div><div class=\"kurss-example\">der Garten — kopsht</div><div class=\"kurss-example\">der Löffel — lugë</div><div class=\"kurss-example\">zählen (ceelen) — numëroj</div><div class=\"kurss-example\">die Nadel — gjilpërë</div><div class=\"kurss-example\">was ist das — çfarë është kjo?</div><div class=\"kurss-example\">der Hammer — çekiç</div><div class=\"kurss-example\">die Hämmer — çekiçë</div><div class=\"kurss-example\">der Deckel (deer dekel) — kapak</div><div class=\"kurss-example\">der Teller — pjatë</div><div class=\"kurss-example\">der Wagen — qerre</div><div class=\"kurss-example\">der Schlitten — slitë</div><div class=\"kurss-example\">das Ding — send</div><div class=\"kurss-example\">die Dinge — sende</div><div class=\"kurss-example\">wie sind die Dinge? — si janë sendet?</div><div class=\"kurss-example\">voll (fol) — plot</div><div class=\"kurss-example\">leer (leer) — bosh</div><div class=\"kurss-example\">schwer (shveer) — i rëndë, i vështirë</div><div class=\"kurss-example\">leicht — i lehtë</div><div class=\"kurss-example\">der Eimer — kovë</div><div class=\"kurss-example\">wieviel (viifiil) — sa</div><div class=\"kurss-example\">wieviel Nadeln — sa gjilpëra</div><div class=\"kurss-example\">hier (hiir) — këtu</div><div class=\"kurss-example\">dort — atje</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Shqiptimi</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ä është umlauti i zanores a dhe shqiptohet si e e shkurtër ose e gjatë e mbyllur.</div><div class=\"kurss-example\">Shembuj: das Mädchen (meet-hjen), die Bänke (dii benke), der Vater (deer faater), die Väter (dii feeter).</div><div class=\"kurss-example\">ü është umlauti i zanores u dhe shqiptohet si y-ja shqipe: buzët rrumbullakosen fort dhe me buzë të rrumbullakosura përpiqesh të thuash i.</div><div class=\"kurss-example\">Shembuj: fünf, der Schlüssel (shlysel).</div><div class=\"kurss-example\">ö shqiptohet me buzë të rrumbullakosura, duke u përpjekur të thuash e: der Löffel.</div><div class=\"kurss-example\">Zanorja e dyfishuar tregon zanore të gjatë: leer (leer).</div><div class=\"kurss-example\">Diftongu eu shqiptohet si oj: neun (nojn).</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramatika</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Gramatika dhe shpjegime</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Parashtesa e theksuar e një foljeje të përbërë në kohën e tashme ndahet nga folja dhe qëndron në fund të fjalisë.</div><div class=\"kurss-example\">Shembuj: hinlegen — er legt hin; aufmachen — er macht auf; anspitzen — er spitzt an.</div><div class=\"kurss-example\">Numërori një, kur përdoret me emër, ka formë për të tri gjinitë: në gjininë mashkullore ein, në femërore eine, në asnjanëse ein.</div><div class=\"kurss-example\">Shembuj: ein Schüler — një nxënës; eine Schülerin — një nxënëse; ein Kind — një fëmijë.</div><div class=\"kurss-example\">Numrat: eins, zwei, drei, vier (fiir), fünf, sechs (zeks), sieben (ziiben), acht, neun (nojn), zehn (ceen).</div><div class=\"kurss-example\">Folja lidhëse në gjermanisht ka formë njëjësi dhe formë shumësi: der Schüler ist klein; die Schüler sind klein.</div><div class=\"kurss-example\">Përemri dëftor në shqip ndryshon sipas gjinisë dhe numrit, si ky, kjo, këta, këto, kurse në gjermanisht përdoret vetëm një formë: das.</div><div class=\"kurss-example\">Shembuj: ky është një çekiç — das ist ein Hammer; kjo është një gjilpërë — das ist eine Nadel; këta janë çekiçë — das sind Hämmer; këto janë gjilpëra — das sind Nadeln.</div><div class=\"kurss-example\">Der Wagen — qerre dhe der Schlitten — slitë në gjermanisht përdoren si në njëjës, ashtu edhe në shumës.</div><div class=\"kurss-example\">Emrat e gjinisë mashkullore dhe asnjanëse me mbaresën -er, -el, -en në shumës shpesh nuk marrin mbaresë.</div><div class=\"kurss-example\">Shembuj: der Hammer — die Hämmer; der Garten — die Gärten; das Fenster — die Fenster; das Messer — die Messer.</div><div class=\"kurss-example\">Emrat e gjinisë femërore me mbaresën -el, -er në shumës marrin -n.</div><div class=\"kurss-example\">Shembuj: die Nadel — die Nadeln; die Feder — die Federn.</div><div class=\"kurss-example\">Përjashtime: die Mutter (nëna) — die Mütter (nënat); die Tochter (bija) — die Töchter (bijat).</div><div class=\"kurss-example\">Nyja joshquese nuk ka shumës: das ist ein Wagen — das sind Wagen; das ist eine Nadel — das sind Nadeln.</div><div class=\"kurss-example\">Në fjalinë dëftore kallëzuesi foljor qëndron në vendin e dytë: er legt den Schlüssel hin; dann legt er den Schlüssel hin.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Përkthe</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson6-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Mësimi 6: kartelë përkthimi\"><span class=\"lesson1-training-progress\">Mësimi 6 · Përkthe: 1 / 21</span><span class=\"lesson1-training-text\">Paul merr një laps dhe vizaton.</span></button><p class=\"lesson1-training-hint\">Kliko mbi kartelë për të parë përkthimin në gjermanisht. Pas përgjigjes, klikimi tjetër shfaq kartelën e radhës.</p></div></div>\n    </details>\n  ",
  "kurssLesson5": "\n    <h3>Mësimi 5</h3>\n    <p class=\"kurss-lesson-intro\">Wen?, akuzativi, sitzen, fragen dhe mbaresa -in.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialogë / fjali</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">Wer sitzt und fragt? Der Lehrer sitzt und fragt.</div>\n        <div class=\"kurss-example\">Wer steht und antwortet? Der Schüler steht und antwortet.</div>\n        <div class=\"kurss-example\">Wie antwortet der Schüler? Der Schüler antwortet gut.</div>\n        <div class=\"kurss-example\">Wen lobt der Lehrer? Der Lehrer lobt den Schüler.</div>\n        <div class=\"kurss-example\">Wie ist der Schüler? Der Schüler ist klein.</div>\n        <div class=\"kurss-example\">Ist der Schüler klein oder groß? Er ist klein.</div>\n        <div class=\"kurss-example\">Wen fragt die Lehrerin? Die Lehrerin fragt die Schülerin.</div>\n        <div class=\"kurss-example\">Wie antwortet die Schülerin? Die Schülerin antwortet schlecht.</div>\n        <div class=\"kurss-example\">Was tut die Lehrerin? Sie tadelt die Schülerin.</div>\n        <div class=\"kurss-example\">Die Schülerin ist nicht klein, sie ist groß.</div>\n        <div class=\"kurss-example\">Ein Kind spielt. Das Kind ist artig.</div>\n        <div class=\"kurss-example\">Die Mutter liebt das Kind. Der Vater lobt das Kind.</div>\n      </div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Fjalët</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">sitzen (zicen) — rri ulur</div>\n        <div class=\"kurss-example\">fragen (fraagen) — pyes</div>\n        <div class=\"kurss-example\">der Lehrer (deer leerer) — mësues</div>\n        <div class=\"kurss-example\">gut (guut) — mirë</div>\n        <div class=\"kurss-example\">wen (veen) — kë</div>\n        <div class=\"kurss-example\">loben — lavdëroj</div>\n        <div class=\"kurss-example\">der Schüler (shyyler) — nxënës</div>\n        <div class=\"kurss-example\">klein — i vogël</div>\n        <div class=\"kurss-example\">groß (groos) — i madh</div>\n        <div class=\"kurss-example\">die Lehrerin — mësuese</div>\n        <div class=\"kurss-example\">die Schülerin — nxënëse</div>\n        <div class=\"kurss-example\">schlecht (shlehjt) — keq</div>\n        <div class=\"kurss-example\">tadeln — qortoj</div>\n        <div class=\"kurss-example\">oder (ooder) — ose</div>\n        <div class=\"kurss-example\">das Kind (kint) — fëmijë</div>\n        <div class=\"kurss-example\">artig (aartihj) — i sjellshëm</div>\n        <div class=\"kurss-example\">die Mutter — nënë</div>\n        <div class=\"kurss-example\">lieben (liiben) — dashuroj</div>\n        <div class=\"kurss-example\">der Vater (faater) — baba</div>\n      </div></div>\n    </details>\n\n        <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Shqiptimi</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">tz është z e dyfishuar dhe shqiptohet si c-ja shqipe: sitzen (zicen).</div>\n        <div class=\"kurss-example\">v në fjalët gjermane shqiptohet si f: der Vater (faater).</div>\n        <div class=\"kurss-example\">ß quhet escet dhe shqiptohet si s-ja shqipe: groß (groos), weiß (vajs).</div>\n      </div></div>\n    </details>\n\n<details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramatika</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Nominativi dhe akuzativi</h4><div class=\"lesson1-grammar-note\">Në shqip nominativi i përgjigjet pyetjes kush?, kurse akuzativi pyetjes kë?.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Në gjermanisht pyetja në nominativ është wer? për personat dhe was? për sendet.</div><div class=\"kurss-example\">Në akuzativ pyetja është wen? për personat dhe was? për sendet.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Ndryshimi i nyjave në akuzativ</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Akkusativ: den Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">sitzen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich sitze</div><div class=\"kurss-example\">du sitzt</div><div class=\"kurss-example\">er/sie/es sitzt</div><div class=\"kurss-example\">wir sitzen</div><div class=\"kurss-example\">ihr sitzt</div><div class=\"kurss-example\">sie sitzen</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">fragen + akuzativ</h4><div class=\"lesson1-grammar-note\">Folja fragen në gjermanisht kërkon akuzativ.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wen fragt der Lehrer?</div><div class=\"kurss-example\">Der Lehrer fragt den Schüler.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Mbaresa -in</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Shumë emra të gjinisë femërore formohen me mbaresën -in.</div><div class=\"kurss-example\">die Lehrerin</div><div class=\"kurss-example\">die Schülerin</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Vendi i foljes</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Në fjalinë dëftore folja qëndron në vendin e dytë.</div><div class=\"kurss-example\">Dann geht das Mädchen hinaus und arbeitet.</div><div class=\"kurss-example\">Das Mädchen geht dann hinaus und arbeitet.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Përkthe</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson5-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Mësimi 5: kartelë përkthimi\"><span class=\"lesson1-training-progress\">Mësimi 5 · Përkthe: 1 / 16</span><span class=\"lesson1-training-text\">Kë dashuron babai?</span></button><p class=\"lesson1-training-hint\">Kliko mbi kartelë për të parë përkthimin në gjermanisht. Pas përgjigjes, klikimi tjetër shfaq kartelën e radhës.</p></div></div>\n    </details>\n  ",
  "kurssLesson4": "            <h3>Mësimi 4</h3>\n            <p class=\"kurss-lesson-intro\">Akuzativi, nehmen, hinlegen, hinausgehen dhe mbiemrat.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialogë / fjali</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Paul kommt und nimmt einen Federhalter.</div><div class=\"kurss-example\">Er zeigt den Federhalter.</div><div class=\"kurss-example\">Er fragt: „Wie ist der Federhalter?“</div><div class=\"kurss-example\">Olga antwortet: „Der Federhalter ist schwarz.“</div><div class=\"kurss-example\">Ist der Federhalter weiß? Nein, der Federhalter ist nicht weiß, er ist schwarz.</div><div class=\"kurss-example\">Marie kommt und nimmt eine Feder.</div><div class=\"kurss-example\">Sie fragt: „Wie ist die Feder?“</div><div class=\"kurss-example\">Olga antwortet: „Die Feder ist spitz.“</div><div class=\"kurss-example\">Ist die Feder stumpf? Nein, die Feder ist nicht stumpf, sie ist spitz.</div><div class=\"kurss-example\">Was legt das Mädchen hin? Es legt die Feder hin.</div><div class=\"kurss-example\">Was nimmst du? Ich nehme ein Messer.</div><div class=\"kurss-example\">Wie ist das Messer? Das Messer ist scharf.</div><div class=\"kurss-example\">Ist das Messer stumpf? Nein, es ist nicht stumpf, es ist scharf.</div><div class=\"kurss-example\">Was legst du hin? Ich lege das Messer, die Feder und den Federhalter hin.</div><div class=\"kurss-example\">Dann gehe ich hinaus und arbeite.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Fjalët</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">nehmen (neemen) — marr</div><div class=\"kurss-example\">er nimmt (nimt) — ai merr</div><div class=\"kurss-example\">der Federhalter (deer feederhalter) — mbajtëse pene</div><div class=\"kurss-example\">einen Federhalter — mbajtëse pene</div><div class=\"kurss-example\">zeigen — tregoj</div><div class=\"kurss-example\">schwarz (shvarc) — i zi</div><div class=\"kurss-example\">weiß (vajs) — i bardhë</div><div class=\"kurss-example\">die Feder (dii feeder) — penë</div><div class=\"kurss-example\">eine Feder — penë</div><div class=\"kurss-example\">spitz (shpic) — me majë</div><div class=\"kurss-example\">hinlegen — vendos</div><div class=\"kurss-example\">legt hin — vendos</div><div class=\"kurss-example\">das Mädchen (meet-hjen) — vajzë</div><div class=\"kurss-example\">das Messer — thikë</div><div class=\"kurss-example\">ein Messer — thikë</div><div class=\"kurss-example\">scharf — i mprehtë</div><div class=\"kurss-example\">stumpf (shtumpf) — i topitur</div><div class=\"kurss-example\">dann — pastaj</div><div class=\"kurss-example\">hinaus — jashtë</div><div class=\"kurss-example\">hinausgehen — dal, dal jashtë</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Shqiptimi</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Mbaresat -en, -er, -el janë të patheksuara, prandaj e-ja në këto mbaresa dëgjohet dobët: kommen, nehmen, der Federhalter.</div><div class=\"kurss-example\">h në gjermanisht mund të jetë si tingull, ashtu edhe shenjë gjatësie për zanoren paraardhëse.</div><div class=\"kurss-example\">Kur h është shenjë gjatësie, ajo nuk shqiptohet si tingull: nehmen (neemen).</div><div class=\"kurss-example\">Kur zanoren e ndjek vetëm një bashkëtingëllore, zanorja shqiptohet e gjatë: die (dii) Feder (feeder), den (deen).</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramatika</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Akuzativi</h4><div class=\"lesson1-grammar-note\">Në gjininë femërore dhe asnjanëse akuzativi është i njëjtë me nominativin. Ndryshon vetëm gjinia mashkullore.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Nominativ: ein Federhalter, eine Feder, ein Messer.</div><div class=\"kurss-example\">Akkusativ: einen Federhalter, eine Feder, ein Messer.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>nehmen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich nehme</div><div class=\"kurss-example\">du nimmst</div><div class=\"kurss-example\">er/sie nimmt</div><div class=\"kurss-example\">wir nehmen</div><div class=\"kurss-example\">ihr nehmt</div><div class=\"kurss-example\">sie nehmen</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Përemrat</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er — gjinia mashkullore</div><div class=\"kurss-example\">sie — gjinia femërore</div><div class=\"kurss-example\">es — gjinia asnjanëse</div><div class=\"kurss-example\">në shumës — sie</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Foljet e ndashme</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">hinlegen → ich lege das Messer hin</div><div class=\"kurss-example\">hinausgehen → Marie geht hinaus</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>Mbiemrat</h4><div class=\"lesson1-grammar-note\">Kur mbiemri në fjali është pjesë emërore e kallëzuesit, ai nuk ndryshon as sipas gjinisë, as sipas numrit.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist klein</div><div class=\"kurss-example\">die Feder ist klein</div><div class=\"kurss-example\">das Messer ist klein</div><div class=\"kurss-example\">die Messer sind klein</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>6</span>Mohimi me nicht</h4><div class=\"lesson1-grammar-note\">Kur nicht mohon një mbiemër, ai qëndron para fjalës që mohohet.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist nicht weiß</div><div class=\"kurss-example\">das Messer ist nicht scharf</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>7</span>-chen / -lein</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Emrat me mbaresën -chen dhe -lein janë të gjinisë asnjanëse: das Mädchen.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Përkthe</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson4-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Mësimi 4: kartelë përkthimi\"><span class=\"lesson1-training-progress\">Mësimi 4 · Përkthe: 1 / 16</span><span class=\"lesson1-training-text\">Vajza merr një mbajtëse pene.</span></button><p class=\"lesson1-training-hint\">Kliko mbi kartelë për të parë përkthimin në gjermanisht. Pas përgjigjes, klikimi tjetër shfaq kartelën e radhës.</p></div></div></details>",
  "kurssLesson3": "            <h3>Mësimi 3</h3>\n            <p class=\"kurss-lesson-intro\">Mësimi i tretë: dialogë, fjalë, shqiptim, gramatikë dhe përkthim.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialogë / fjali</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wer rechnet und zeichnet?<br>Wir rechnen und zeichnen.</div><div class=\"kurss-example\">Wer kommt?<br>Paul und Anna kommen.</div><div class=\"kurss-example\">Was steht hier?<br>Hier steht ein Tisch.</div><div class=\"kurss-example\">Was steht dort?<br>Dort steht eine Bank.</div><div class=\"kurss-example\">Was liegt hier?<br>Hier liegt ein Buch.</div><div class=\"kurss-example\">Was liegt dort?<br>Dort liegt ein Heft.</div><div class=\"kurss-example\">Was hängt hier?<br>Hier hängt ein Bild.</div><div class=\"kurss-example\">Was hängt dort?<br>Dort hängt eine Tafel.</div><div class=\"kurss-example\">Wie ist das Buch?<br>Das Buch ist dick.</div><div class=\"kurss-example\">Wie ist das Heft?<br>Das Heft ist dünn.</div><div class=\"kurss-example\">Wie ist die Bank?<br>Die Bank ist niedrig.</div><div class=\"kurss-example\">Wie ist der Tisch?<br>Der Tisch ist hoch.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Fjalët</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wer — kush</div><div class=\"kurss-example\">was — çfarë</div><div class=\"kurss-example\">hier — këtu</div><div class=\"kurss-example\">dort — atje</div><div class=\"kurss-example\">der Tisch — tryezë</div><div class=\"kurss-example\">ein Tisch — tryezë</div><div class=\"kurss-example\">die Bank — bankë</div><div class=\"kurss-example\">eine Bank — bankë</div><div class=\"kurss-example\">liegen — rri shtrirë</div><div class=\"kurss-example\">liegt hier ein Buch? — a ka / ndodhet këtu një libër?</div><div class=\"kurss-example\">das Buch — libër</div><div class=\"kurss-example\">ein Buch — libër</div><div class=\"kurss-example\">hängen — varem</div><div class=\"kurss-example\">das Bild — pikturë</div><div class=\"kurss-example\">ein Bild — pikturë</div><div class=\"kurss-example\">die Tafel — dërrasë e zezë</div><div class=\"kurss-example\">eine Tafel — dërrasë e zezë</div><div class=\"kurss-example\">wie — si</div><div class=\"kurss-example\">ist — është</div><div class=\"kurss-example\">dick — i trashë</div><div class=\"kurss-example\">das Heft — fletore</div><div class=\"kurss-example\">ein Heft — fletore</div><div class=\"kurss-example\">dünn — i hollë</div><div class=\"kurss-example\">niedrig — i ulët</div><div class=\"kurss-example\">hoch — i lartë</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Shqiptimi</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Tingulli i gjatë i në gjermanisht shënohet me ie: liegen (liigen), hier (hiir), wie (vii).</div><div class=\"kurss-example\">ck është k e dyfishtë: dick (dikk).</div><div class=\"kurss-example\">Te mbiemrat dhe ndajfoljet mbaresa -ig tingëllon si një -ihj e butë: niedrig (niidrihj).</div><div class=\"kurss-example\">Nëse pas mbaresës -ig vjen e: -ige, atëherë g shqiptohet si g e qartë: niedrige (niidrige) Bänke.</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramatika</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Kryefjala</h4><div class=\"lesson1-grammar-note\">Kryefjala në gjermanisht i përgjigjet pyetjes wer? / was? dhe qëndron në nominativ.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Me wer? pyetet për persona.</div><div class=\"kurss-example\">Me was? pyetet për sende.</div><div class=\"kurss-example\">Wer singt? — Sie singt.</div><div class=\"kurss-example\">Was liegt hier? — Hier liegt ein Buch.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Nyjat</h4><div class=\"lesson1-grammar-note\">Në gjermanisht emrat kanë 3 gjini: mashkullore, femërore dhe asnjanëse. Para emrave zakonisht qëndron një fjalë e vogël që quhet nyje. Kjo fjalë nuk përkthehet.</div><h5 class=\"lesson2-subtitle\">Nyja shquese</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">gjinia mashkullore — der</div><div class=\"kurss-example\">gjinia femërore — die</div><div class=\"kurss-example\">gjinia asnjanëse — das</div><div class=\"kurss-example\">Në shumës nyja shquese për të tri gjinitë është die.</div><div class=\"kurss-example\">der Tisch — die Tische</div><div class=\"kurss-example\">die Bank — die Bänke</div><div class=\"kurss-example\">das Heft — die Hefte</div></div><h5 class=\"lesson2-subtitle\">Nyja joshquese</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">gjinia mashkullore — ein</div><div class=\"kurss-example\">gjinia femërore — eine</div><div class=\"kurss-example\">gjinia asnjanëse — ein</div><div class=\"kurss-example\">Nyja joshquese nuk ka shumës.</div><div class=\"kurss-example\">ein Tisch — Tische</div><div class=\"kurss-example\">ein Heft — Hefte</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Emrat e përveçëm</h4><div class=\"lesson1-grammar-note\">Para emrave të përveçëm nuk përdoret nyja.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans spielt, aber Marie singt.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Vendi i foljes</h4><div class=\"lesson1-grammar-note\">Në fjalinë dëftore folja qëndron në vendin e dytë.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier hängt eine Karte.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>stehen / liegen / hängen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Në gjermanisht për sendet që janë në pozicion vertikal thuhet se ato qëndrojnë:<br>der Tisch steht<br>die Bank steht</div><div class=\"kurss-example\">Për sendet që ndodhen në pozicion horizontal thuhet se ato rrinë shtrirë:<br>das Buch liegt<br>das Heft liegt</div><div class=\"kurss-example\">Sendet mund edhe të varen:<br>die Karte hängt<br>die Tafel hängt</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Përkthe</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson3-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Mësimi 3: kartelë përkthimi\"><span class=\"lesson1-training-progress\">Mësimi 3 · Përkthe: 1 / 22</span><span class=\"lesson1-training-text\">A llogarit ti?</span></button><p class=\"lesson1-training-hint\">Kliko mbi kartelë për të parë përkthimin në gjermanisht. Pas përgjigjes, klikimi tjetër shfaq kartelën e radhës.</p></div></div></details>",
  "kurssLesson7": "            <h3>Mësimi 7</h3>\n            <p class=\"kurss-lesson-intro\">Mësimi i shtatë: mënyra urdhërore, forma e mirësjelljes dhe shumësi.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialogë / fjali</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans, singe ein Lied! Was tust du? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans und Olga, singt ein Lied! Was tut ihr? Wir singen ein Lied.</div><div class=\"kurss-example\">Fräulein Müller, singen Sie, bitte, ein Lied! Was tun Sie? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans, zähle die Teller! Was tut Hans? Er zählt die Teller.</div><div class=\"kurss-example\">Hans und Olga, zählt die Teller! Was tun Hans und Olga? Sie zählen die Teller.</div><div class=\"kurss-example\">Fräulein Müller, zählen Sie, bitte, die Teller!</div><div class=\"kurss-example\">Hans, öffne das Fenster! Was tut Hans? Er öffnet das Fenster.</div><div class=\"kurss-example\">Hans und Olga, öffnet die Fenster! Was tun Hans und Olga? Sie öffnen die Fenster.</div><div class=\"kurss-example\">Fräulein Müller, öffnen Sie, bitte, alle Fenster!</div><div class=\"kurss-example\">Fräulein Müller öffnet alle Fenster.</div><div class=\"kurss-example\">Das ist der Spiegel. Das sind die Spiegel.</div><div class=\"kurss-example\">Das ist der Lappen. Das sind die Lappen.</div><div class=\"kurss-example\">Das ist der Spaten. Das sind die Spaten.</div><div class=\"kurss-example\">Das ist der Besen. Das sind die Besen.</div><div class=\"kurss-example\">Das ist die Schaufel. Das sind die Schaufeln.</div><div class=\"kurss-example\">Das ist die Schüssel. Das sind die Schüsseln.</div><div class=\"kurss-example\">Das ist das Zimmer. Das sind die Zimmer.</div><div class=\"kurss-example\">Das ist das Ufer. Das sind die Ufer.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Fjalët</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">singen — këndoj</div><div class=\"kurss-example\">singe — këndo</div><div class=\"kurss-example\">singt — këndoni</div><div class=\"kurss-example\">singen Sie — këndoni</div><div class=\"kurss-example\">das Lied (das liit) — këngë</div><div class=\"kurss-example\">Sie — Ju</div><div class=\"kurss-example\">zählen — numëroj</div><div class=\"kurss-example\">das Fräulein (frojlajn) — zonjushë</div><div class=\"kurss-example\">der Müller — mullixhi</div><div class=\"kurss-example\">öffnen — hap</div><div class=\"kurss-example\">das Fenster (fenster) — dritare</div><div class=\"kurss-example\">alle — të gjithë</div><div class=\"kurss-example\">der Spiegel (shpiigel) — pasqyrë</div><div class=\"kurss-example\">der Lappen — leckë</div><div class=\"kurss-example\">der Spaten — lopatë</div><div class=\"kurss-example\">der Besen — fshesë</div><div class=\"kurss-example\">die Schaufel — lopatëz</div><div class=\"kurss-example\">die Schüssel — tas</div><div class=\"kurss-example\">das Zimmer — dhomë</div><div class=\"kurss-example\">das Ufer (uufer) — breg</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Shqiptimi</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">sp në fillim të fjalës ose të rrokjes shqiptohet si shp: der Spiegel (deer shpiigel).</div><div class=\"kurss-example\">sch shqiptohet si sh-ja shqipe: die Schaufel (dii shaufel), die Schüssel (dii shysel).</div><div class=\"kurss-example\">Diftongu äu shqiptohet si oj në shqip: das Fräulein (das frojlajn).</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramatika</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Mënyra urdhërore</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Mënyra urdhërore në vetën e 2. njëjës përputhet me vetën e 2. njëjës të foljes pa mbaresën vetore -st, duke i shtuar mbaresën -e.</div><div class=\"kurss-example\">Shembuj: antworte!, arbeite!, öffne!, zeichne!</div><div class=\"kurss-example\">Shumë shpesh mbaresa -e nuk përdoret dhe forma urdhërore bëhet njërrokëshe: geh!, steh!, komm!, tu!, sing!, frag!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Urdhërorja në shumës</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Forma urdhërore në vetën e 2. shumës është e njëjtë me vetën e 2. shumës të kohës së tashme, por përdoret pa përemër.</div><div class=\"kurss-example\">Shembuj: antwortet!, arbeitet!, öffnet!, zeichnet!, geht!, steht!, tut!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Forma e mirësjelljes me Sie</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Forma e mirësjelljes me “Ju” përputhet me vetën e 3. shumës. Përemri Sie shkruhet me shkronjë të madhe dhe qëndron pas foljes.</div><div class=\"kurss-example\">Shembuj: antworten Sie!, arbeiten Sie!, öffnen Sie!, zeichnen Sie!, gehen Sie!, stehen Sie!, tun Sie!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>öffnen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Te folja öffnen, për shqiptim më të lehtë, në vetën e 2. dhe të 3. njëjës dhe në vetën e 2. shumës midis temës dhe mbaresës futet një e: du öffnest, er öffnet, ihr öffnet.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Übung / Ushtrim</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson7-exercise-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Mësimi 7: kartelë ushtrimi\"><span class=\"lesson1-training-progress\">Mësimi 7 · Übung: 1 / 16</span><span class=\"lesson1-training-text\">fragen — pyes</span></button><p class=\"lesson1-training-hint\">Prek kartelën për të parë format urdhërore.</p></div></div></details>",
  "kurssLesson1": "            <h3>Mësimi 1</h3>\n            <p class=\"kurss-lesson-intro\">Mësimi i parë: foljet në kohën e tashme, fjalët, shqiptimi, gramatika dhe përkthimi.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Foljet në kohën e tashme</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info\">Foljet dhe zgjedhimi i tyre në kohën e tashme.</div>\n                <div class=\"lesson1-verb-cards\">\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>kommen — vij</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>komme</strong><span>unë vij</span><span>du</span><strong>kommst</strong><span>ti vjen</span><span>er / sie</span><strong>kommt</strong><span>ai / ajo vjen</span><span>wir</span><strong>kommen</strong><span>ne vijmë</span><span>ihr</span><strong>kommt</strong><span>ju vini</span><span>sie / Sie</span><strong>kommen</strong><span>ata vijnë / Ju vini</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>gehen — shkoj</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>gehe</strong><span>unë shkoj</span><span>du</span><strong>gehst</strong><span>ti shkon</span><span>er / sie</span><strong>geht</strong><span>ai / ajo shkon</span><span>wir</span><strong>gehen</strong><span>ne shkojmë</span><span>ihr</span><strong>geht</strong><span>ju shkoni</span><span>sie / Sie</span><strong>gehen</strong><span>ata shkojnë / Ju shkoni</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>stehen — qëndroj</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>stehe</strong><span>unë qëndroj</span><span>du</span><strong>stehst</strong><span>ti qëndron</span><span>er / sie</span><strong>steht</strong><span>ai / ajo qëndron</span><span>wir</span><strong>stehen</strong><span>ne qëndrojmë</span><span>ihr</span><strong>steht</strong><span>ju qëndroni</span><span>sie / Sie</span><strong>stehen</strong><span>ata qëndrojnë / Ju qëndroni</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>singen — këndoj</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>singe</strong><span>unë këndoj</span><span>du</span><strong>singst</strong><span>ti këndon</span><span>er / sie</span><strong>singt</strong><span>ai / ajo këndon</span><span>wir</span><strong>singen</strong><span>ne këndojmë</span><span>ihr</span><strong>singt</strong><span>ju këndoni</span><span>sie / Sie</span><strong>singen</strong><span>ata këndojnë / Ju këndoni</span></div>\n                  </article>\n                </div>\n                <section class=\"lesson1-block\">\n                  <h4>Shembuj</h4>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Stehst du?<br>Ja, ich stehe.</div><div class=\"kurss-example\">Steht Albert?<br>Ja, er steht.</div><div class=\"kurss-example\">Steht Marta?<br>Ja, sie steht.</div><div class=\"kurss-example\">Wer kommt und singt?<br>Albert und Marta kommen und singen.</div><div class=\"kurss-example\">Geht ihr?<br>Ja, wir gehen.</div><div class=\"kurss-example\">Wer steht und singt?<br>Albert und Marta stehen und singen.</div></div>\n                </section>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Fjalët</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info lesson1-vardini-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>Shqiptimi i përafërt i fjalëve jepet në kllapa me shkronja shqipe.<br>Kjo duhet mbajtur parasysh edhe në mësimet e mëtejshme.</span></div>\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wir (viir) — ne</div><div class=\"kurss-example\">Në fjalën “wir” shkronja i shqiptohet e gjatë.</div><div class=\"kurss-example\">kommen (komen) — vij</div><div class=\"kurss-example\">gehen (gee-en) — shkoj</div><div class=\"kurss-example\">stehen (shtee-en) — qëndroj</div><div class=\"kurss-example\">singen (zingen) — këndoj</div><div class=\"kurss-example\">du (duu) kommst — ti vjen</div><div class=\"kurss-example\">er (eer) kommt — ai vjen</div><div class=\"kurss-example\">sie (zii) kommt — ajo vjen</div><div class=\"kurss-example\">wer (veer) — kush?</div><div class=\"kurss-example\">ja (jaa) — po</div></div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Shqiptimi</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Shqiptimi i saktë i fjalëve, i shënuar me shkronja shqipe, jepet në mësime.</div><div class=\"kurss-example\">Wir (viir) — ne. Në fjalën wir, i shqiptohet gjithmonë e gjatë.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramatika</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>∞</span>Infinitivi</h4><div class=\"lesson1-grammar-note\">Forma bazë e foljes. Zakonisht infinitivi mbaron me -en.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">kommen</div><div class=\"kurss-example\">gehen</div><div class=\"kurss-example\">stehen</div><div class=\"kurss-example\">singen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♟</span>Mbaresat e kohës së tashme</h4><div class=\"lesson1-ending-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><div class=\"lesson1-ending-info-body\"><p><strong>Hiq <span class=\"lesson1-ending-accent\">-en</span> nga forma bazë e foljes dhe shto mbaresën.</strong></p><p>Shembull: kommen → komm + mbaresa</p><div class=\"lesson1-ending-process\" aria-label=\"Si formohen mbaresat e kohës së tashme\"><div class=\"lesson1-ending-step\"><strong>kommen</strong><span>forma bazë</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>hiq <span class=\"lesson1-ending-accent\">-en</span></strong><span>mbetet rrënja</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>komm</strong><span>rrënja</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>shto mbaresën</strong><span>e / st / t</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-results\"><div>komm + <span class=\"lesson1-ending-accent\">e</span> = <strong>komme</strong></div><div>komm + <span class=\"lesson1-ending-accent\">st</span> = <strong>kommst</strong></div><div>komm + <span class=\"lesson1-ending-accent\">t</span> = <strong>kommt</strong></div></div></div></div></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich → -e</div><div class=\"kurss-example\">du → -st</div><div class=\"kurss-example\">er / sie → -t</div><div class=\"kurss-example\">wir → -en</div><div class=\"kurss-example\">ihr → -t</div><div class=\"kurss-example\">sie → -en</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>●</span>Shembuj</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich komme</div><div class=\"kurss-example\">du kommst</div><div class=\"kurss-example\">er kommt</div><div class=\"kurss-example\">wir kommen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>?</span>Fjalitë pyetëse</h4><div class=\"lesson1-grammar-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>Në fjalinë pyetëse gjermane folja zakonisht kalon në vendin e parë.</span></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Në shqip:<br>Ti vjen.<br>A vjen ti?</div><div class=\"kurss-example\">Në gjermanisht:<br>Du kommst.<br>Kommst du?</div><div class=\"kurss-example\">du kommst — ti vjen<br>kommst du? — a vjen ti?</div><div class=\"kurss-example\">er singt — ai këndon<br>singt er? — a këndon ai?</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♣</span>Dallimi i vetës</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er kommt — ai vjen</div><div class=\"kurss-example\">sie kommt — ajo vjen</div><div class=\"kurss-example\">sie kommen — ata / ato vijnë</div></div></section>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Përkthe</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson1-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Mësimi 1: kartelë ushtrimi\">\n                    <span class=\"lesson1-training-progress\">Mësimi 1 · Përkthe: 1 / 11</span>\n                    <span class=\"lesson1-training-text\">A vjen ti?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Kliko mbi kartelë për të parë përkthimin në gjermanisht. Pas përgjigjes, klikimi tjetër shfaq kartelën e radhës.</p>\n                </div>\n              </div>\n            </details>"
};

